@import "tailwindcss";
@import "tw-animate-css";

/* State normalization (architecture.md §2 — "Normalize state before sharing").
   "highlighted item" unifies the three state vocabularies of the libraries
   (:focus from the menu, [data-highlighted] from combobox, [data-selected]
   from command). One line covers all of them; a new library joins by adding a
   selector here, not a React translation layer. Do NOT use data-active for
   this — data-active already means "current item". */
@custom-variant highlighted (&:is(:focus, [data-highlighted], [data-selected]));

/* Field-focus normalization. The row's outline must fire only when the
   CONTROL is focused — not any button inside it (addon, inset). That is why
   this variant matches the `.field-control` marker (present on field.control,
   SelectTrigger and on checkbox/radio/switch), and not bare `:focus-within`,
   which would match any focused descendant.
   `:is(.field-control:focus-within)` covers the case where the element itself
   is the control (checkbox/radio/switch); `:has(.field-control:focus-within)`
   covers the case where the control is a descendant (row > body > input,
   row > select-trigger). `field-focus:` is consumed by the field family. */
@custom-variant field-focus (
    &:is(.field-control:focus-within),
    &:has(.field-control:focus-within)
);

@theme inline {
    --default-transition-duration: 300ms;

    --color-*: initial;

    /* The 6 roles (architecture.md §1). base = the color of this palette;
       soft = a subtle background; line = stroke; contrast = content on
       base/shade; accent = content on a foreign background or on soft. */
    --color-palette-base: var(--palette-base);
    --color-palette-soft: var(--palette-soft);
    --color-palette-line: var(--palette-line);
    --color-palette-contrast: var(--palette-contrast);
    --color-palette-accent: var(--palette-accent);

    /* The 6th role — INTERACTION highlight: focus outline, ring, active
       indicator. It is the only role drawn OUTSIDE the element: it contrasts
       with what is BEHIND it, not with what it contains. That is why it never
       fit into any of the other five.

       EVERY palette declares `--palette-ring`, no exceptions. A palette that
       does not theme focus uses `var(--palette-accent)`. It is NOT optional:
       custom properties inherit, and a palette that omits a role inherits it
       from an ancestor — that is how an invalid field inside a feature ended
       up with a red border and a purple focus ring. In an inheritance-based
       system, "optional token" leaks from the outer scope. */
    --color-palette-ring: var(--palette-ring, var(--palette-accent));

    /* Hover of a painted background — DERIVATION, not a contract role.
       This was the `shade` token, removed: it had a single use (solid button
       hover) and no palette ever overrode it — always the same formula. A
       token that is always derived and never customized is a derivation, not
       a role. `soft` does not replace it: on brand, base is 0.55 and soft
       0.95 — it would lighten too much. Need two distinct backgrounds? Create
       another surface palette (surface/raised already are that). The
       `--palette-base-hover` escape hatch exists for when the derivation does
       not fit; the fallback here is safe because it is read from no palette,
       so there is no inheritance to leak. */
    --color-palette-base-hover: var(
        --palette-base-hover,
        oklch(from var(--palette-base) calc(l + var(--palette-state-shift)) c h)
    );

    /* Outside the palette contract */
    --color-scrim: oklch(0 0 0 / 0.4);

    /* Chart series — their own axis, see the categorical derivation block
       below. Outside the palette contract by design: no role describes "the
       third series", and reusing `danger` as series 4 breaks its meaning. */
    --color-chart-1: var(--chart-1);
    --color-chart-2: var(--chart-2);
    --color-chart-3: var(--chart-3);
    --color-chart-4: var(--chart-4);
    --color-chart-5: var(--chart-5);
    --color-chart-6: var(--chart-6);
    --color-chart-7: var(--chart-7);
    --color-chart-8: var(--chart-8);

    /* Ordinal ramp — derived from the active palette, see below. */
    --color-chart-ramp-1: var(--chart-ramp-1);
    --color-chart-ramp-2: var(--chart-ramp-2);
    --color-chart-ramp-3: var(--chart-ramp-3);
    --color-chart-ramp-4: var(--chart-ramp-4);
    --color-chart-ramp-5: var(--chart-ramp-5);

    --radius-*: initial;
    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 16px;
    --radius-full: 9999px;

    --font-sans:
        -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial,
        sans-serif;

    /* Typography and breakpoints use Tailwind's scale, with no tokens of their
       own. Same reason as spacing (architecture.md §4): they are continuous
       scales without semantics — `sm` says nothing that Tailwind's `sm` does
       not, and keeping a parallel scale created two living systems at once.

       Breakpoints, beyond that, are a layout decision of the APPLICATION, not
       of the design system. The four device-named breakpoints (mobile/tablet/
       laptop/desktop) had ZERO uses, and a device name on a min-width lies:
       `tablet:` fires on desktop too.

       Whoever wants another scale overrides Tailwind's defaults. */

    /* Control height. Was --spacing-control-height, removed for living in the
       spacing namespace (it generated p-control-height, gap-control-height).
       It now lives in the --height-* namespace, which only generates
       h-/min-h-/max-h-control — never p-/gap-/w-. */
    --height-control: 2.25rem;

    /* Progress indeterminate animation. The segment (1/3 width) slides across
       the rail. `inset-inline-start` is a logical property, so the slide
       direction inverts under RTL automatically — no separate keyframe, no
       `rtl:` variant. `motion-reduce:` on the indicator disables it. */
    --animate-progress-indeterminate: progress-indeterminate 1.5s ease-in-out
        infinite;
}

@keyframes progress-indeterminate {
    from {
        inset-inline-start: -33%;
    }
    to {
        inset-inline-start: 100%;
    }
}

/* Density swappable per subtree (architecture.md §4). */
[data-density="compact"] {
    --spacing: 0.2rem;
}

[data-density="spacious"] {
    --spacing: 0.3rem;
}

/* Hover direction per theme: hover darkens in light, lightens in dark.
   Consumed by the --color-palette-base-hover derivation above. This is theme
   machinery, not a palette, so it lives here rather than being duplicated
   into every palette file. */
:root[data-theme="light"] {
    --palette-state-shift: -0.1;
}

:root[data-theme="dark"] {
    --palette-state-shift: 0.1;
}

/* Categorical chart series — DERIVED from the active palette.
   Slot 1 IS the palette's color; the rest rotate hue from it. This is not a
   monochromatic ramp — each slot is a distinct hue, which preserves identity.

   The offsets (+180, -70, +60, -150) and the lightness of each slot came
   from search, maximizing colourblind separation in the WORST case across
   the project's palettes. Worst case measured (ΔE OKLab ×100, protan/deutan
   @ 1.0): light 11.5 · dark 9.4  (target >= 8).

   Uniform hue rotation would NOT guarantee that: protanopia and deuteranopia
   collapse the green–red axis, so equidistant hues can become the same color.
   That is why these offsets are measured, not chosen for aesthetics.

   Chroma drops on the light slots: keeping it high blows the gamut and the
   real lightness escapes the band.

   This block lives in global.css, not in a palette file: it is theme
   machinery (it reads --palette-base), declared once and inherited by every
   palette. Putting it per-palette would duplicate identical rules; it is not
   a palette, it is a derivation over one. */
:root[data-theme="light"] [class*="palette-"] {
    /* clamp + chroma minimum: a too-light base (surface = oklch(1 0 0))
       would come out white and colorless. Slots 2..5 already use absolute
       L and C. */
    --chart-1: oklch(
        from var(--palette-base) clamp(0.43, l, 0.68) max(c, 0.14) h
    );
    --chart-2: oklch(from var(--palette-base) 0.68 0.13 calc(h + 180));
    --chart-3: oklch(from var(--palette-base) 0.5 0.19 calc(h - 70));
    --chart-4: oklch(from var(--palette-base) 0.72 0.13 calc(h + 60));
    --chart-5: oklch(from var(--palette-base) 0.56 0.19 calc(h - 150));
    --chart-ramp-1: oklch(from var(--palette-base) 0.78 0.16 h);
    --chart-ramp-2: oklch(from var(--palette-base) 0.68 0.16 h);
    --chart-ramp-3: oklch(from var(--palette-base) 0.58 0.16 h);
    --chart-ramp-4: oklch(from var(--palette-base) 0.48 0.16 h);
    --chart-ramp-5: oklch(from var(--palette-base) 0.38 0.16 h);
}

:root[data-theme="dark"] [class*="palette-"] {
    /* In dark the anchor inverts (dark → light), otherwise the light tip
       disappears into the background. */
    --chart-1: oklch(
        from var(--palette-base) clamp(0.52, l, 0.72) max(c, 0.13) h
    );
    --chart-2: oklch(from var(--palette-base) 0.62 0.13 calc(h + 180));
    --chart-3: oklch(from var(--palette-base) 0.52 0.18 calc(h - 70));
    --chart-4: oklch(from var(--palette-base) 0.66 0.13 calc(h + 60));
    --chart-5: oklch(from var(--palette-base) 0.56 0.18 calc(h - 150));
    --chart-ramp-1: oklch(from var(--palette-base) 0.48 0.15 h);
    --chart-ramp-2: oklch(from var(--palette-base) 0.56 0.15 h);
    --chart-ramp-3: oklch(from var(--palette-base) 0.64 0.15 h);
    --chart-ramp-4: oklch(from var(--palette-base) 0.72 0.15 h);
    --chart-ramp-5: oklch(from var(--palette-base) 0.8 0.15 h);
}

html,
body {
    min-height: 100%;
}

body {
    margin: 0;
}

* {
    box-sizing: border-box;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    -webkit-tap-highlight-color: transparent;
}

/* A palette does not paint (architecture.md §1) — the body applies roles
   explicitly. palette-surface is a custom class (not a utility); it goes on
   <body> via the root layout. */
body {
    @apply bg-palette-base text-palette-contrast font-sans text-sm antialiased;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    @apply font-semibold;
}

a {
    cursor: pointer;
}

button {
    cursor: pointer;
}
